{
  "name": "被动监测实验界面与通信组件",
  "name_en": "Passive Monitoring GUI and Communication Component",
  "manufacturer": "",
  "description": "这是一个非物理软件组件，用于被动监测实验中的仪器通信与图形界面控制。它负责连接并协调 Keithley 2400 与 Lake Shore 仪器，执行实验配置、读取测量数据、记录日志，以及管理界面状态与实验流程。",
  "description_en": "This is a non-physical software component for instrument communication and GUI control in passive monitoring experiments. It connects and coordinates a Keithley 2400 and a Lake Shore instrument, handling experiment configuration, measurement retrieval, logging, and UI workflow management.",
  "actions": [
    {
      "action_name": "auto-configure_instruments",
      "description": "配置被动监测实验所需的仪器参数。",
      "description_en": "Configure the instruments for a passive monitoring experiment."
    },
    {
      "action_name": "auto-connect",
      "description": "连接 Keithley 2400 与 Lake Shore 仪器的通信会话。",
      "description_en": "Connect communication sessions to the Keithley 2400 and the Lake Shore instrument."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭被动监测会话并安全结束仪器通信。",
      "description_en": "Shut down the passive monitoring session and safely end instrument communication."
    },
    {
      "action_name": "auto-get_measurement",
      "description": "获取当前测量数据。",
      "description_en": "get current measurement data"
    },
    {
      "action_name": "auto-setup_styles",
      "description": "设置图形界面的样式。",
      "description_en": "Set up the GUI styles."
    },
    {
      "action_name": "auto-create_widgets",
      "description": "创建图形界面的控件组件。",
      "description_en": "Create the GUI widgets and controls."
    },
    {
      "action_name": "auto-log",
      "description": "记录实验运行中的日志信息。",
      "description_en": "Log messages during experiment operation."
    },
    {
      "action_name": "auto-start_experiment",
      "description": "启动被动监测实验流程。",
      "description_en": "Start the passive monitoring experiment workflow."
    },
    {
      "action_name": "auto-stop_experiment",
      "description": "停止被动监测实验流程。",
      "description_en": "Stop the passive monitoring experiment workflow."
    },
    {
      "action_name": "auto-set_ui_state",
      "description": "设置图形界面的状态。",
      "description_en": "Set the state of the GUI."
    }
  ],
  "tag_hints": [
    "passive monitoring",
    "experiment GUI",
    "VISA instrument communication",
    "Keithley 2400 integration",
    "Lake Shore integration",
    "measurement retrieval",
    "data logging"
  ]
}

